const payload = $input.first()?.json;
if (!payload || payload.schema_version !== 1 || payload.send_enabled !== false || !Array.isArray(payload.items) || payload.items.length > 10) {
  throw new Error("Lote de análise inválido.");
}
return payload.items.map((job, index) => {
  if (!job || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(job.claim_id) ||
      !Number.isSafeInteger(job.message_id) || job.message_id < 1 ||
      !["instagram", "waha"].includes(job.origin) ||
      typeof job.text !== "string" || job.text.length === 0 || job.text.length > 8192 ||
      !Number.isInteger(job.attempt) || job.attempt < 1 || job.attempt > 3) {
    throw new Error("Item de análise inválido.");
  }
  return { json: { claim_id: job.claim_id, message_id: job.message_id, origin: job.origin, text: job.text }, pairedItem: { item: 0 } };
});

const claims = $("Validar lote").all();
const predictions = $input.all();
if (!claims.length || claims.length !== predictions.length || predictions.length > 10) {
  throw new Error("Quantidade de análises incompatível.");
}
const sentiments = ["positive", "negative", "neutral", "uncertain"];
const confidence = ["low", "medium", "high"];
return predictions.map((item, index) => {
  const content = item.json?.choices?.[0]?.message?.content;
  if (typeof content !== "string" || content.length > 4096) {
    throw new Error("Modelo retornou resposta inválida.");
  }
  let response;
  try { response = JSON.parse(content); } catch { throw new Error("Modelo não retornou JSON."); }
  if (!response || typeof response !== "object" || Array.isArray(response) ||
      Object.keys(response).sort().join(",") !== "confidence,explanation,sentiment" ||
      !sentiments.includes(response.sentiment) || !confidence.includes(response.confidence) ||
      typeof response.explanation !== "string") {
    throw new Error("Classificação fora do contrato.");
  }
  const explanation = [...response.explanation.trim()].slice(0, 120).join("");
  if (!explanation || /[\u0000-\u0008\u000B\u000C\u000E-\u001F]/.test(explanation)) {
    throw new Error("Explicação inválida.");
  }
  return {
    json: {
      claim_id: claims[index].json.claim_id,
      sentiment: response.sentiment,
      confidence: response.confidence,
      explanation
    },
    pairedItem: { item: index }
  };
});
